local SaltRefiner = {}
local PRODUCTS = {
    sea_salt = { name = "Morska sol", seawaterCost = 2, fuelCost = 1, time = 2, cost = 12, purity = 60, description = "Morska sol iz izhlapene morske vode." },
    rock_salt = { name = "Kamena sol", saltOreCost = 2, time = 3, cost = 28, purity = 70, prestige = 1, description = "Kamena sol iz rudnikov." },
    refined_salt = { name = "Rafinirana sol", saltOreCost = 3, waterCost = 1, fuelCost = 1, time = 5, cost = 70, purity = 85, prestige = 2, happiness = 1, description = "Rafinirana sol z visoko čistostjo." },
    table_salt = { name = "Namizna sol", saltOreCost = 3, waterCost = 2, fuelCost = 1, time = 7, cost = 160, purity = 95, prestige = 5, happiness = 2, description = "Namizna sol za vsakdanjo rabo." },
    silver_treated_salt = { name = "Srebrno obdelana sol", saltOreCost = 4, waterCost = 2, silverCost = 1, fuelCost = 1, time = 10, cost = 380, purity = 98, prestige = 11, happiness = 3, description = "Srebrno obdelana sol za kraljeve jedi." },
    royal_pure_salt = { name = "Kraljevski čista sol", saltOreCost = 6, waterCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, fuelCost = 2, time = 15, cost = 1200, purity = 100, prestige = 35, happiness = 8, description = "Velika kraljevska čista sol z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Solinarska delavnica", cost = { gold = 280, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    pan_house = { name = "Izparjevalnica", cost = { gold = 900, wood = 250, stone = 400, fuel = 8 }, upkeep = 22, qualityBonus = 18 },
    crystallization_room = { name = "Kristalizirnica", cost = { gold = 2200, wood = 350, stone = 700, silver = 30, water = 10 }, upkeep = 55, qualityBonus = 30 },
    royal_salt_atelier = { name = "Kraljevski atelje soli", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
SaltRefiner.seawaterStock = 16; SaltRefiner.saltOreStock = 16; SaltRefiner.waterStock = 14; SaltRefiner.fuelStock = 14; SaltRefiner.silverStock = 8; SaltRefiner.goldStock = 6; SaltRefiner.jewelStock = 6
SaltRefiner.productStock = {}; SaltRefiner.buildings = {}; SaltRefiner.maker = nil; SaltRefiner.activeMaking = {}; SaltRefiner.totalProducts = 0; SaltRefiner.dayTimer = 0
function SaltRefiner.init() SaltRefiner.seawaterStock=16; SaltRefiner.saltOreStock=16; SaltRefiner.waterStock=14; SaltRefiner.fuelStock=14; SaltRefiner.silverStock=8; SaltRefiner.goldStock=6; SaltRefiner.jewelStock=6; SaltRefiner.productStock={}; SaltRefiner.buildings={}; SaltRefiner.maker=nil; SaltRefiner.activeMaking={}; SaltRefiner.totalProducts=0; SaltRefiner.dayTimer=0; print("[SaltRefiner] Royal Salt Refiner System initialized (6 products, 4 buildings)") end
function SaltRefiner.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SaltRefiner.maker={name=n or ("Solinar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Solinar najet: %s (spretnost: %d)",SaltRefiner.maker.name,s),"success") end; return true end
function SaltRefiner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SaltRefiner.build(id) local ok,e=SaltRefiner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SaltRefiner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SaltRefiner.getQualityBonus() local b=0; for _,bd in ipairs(SaltRefiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SaltRefiner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.seawaterCost and SaltRefiner.seawaterStock<(d.seawaterCost or 0) then return false,"Premalo morske vode" end; if d.saltOreCost and SaltRefiner.saltOreStock<(d.saltOreCost or 0) then return false,"Premalo solne rude" end; if d.waterCost and SaltRefiner.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.fuelCost and SaltRefiner.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.silverCost and SaltRefiner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SaltRefiner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SaltRefiner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #SaltRefiner.buildings==0 then return false,"Potrebna delavnica" end; if not SaltRefiner.maker then return false,"Potreben solinar" end; return true end
function SaltRefiner.make(pt,qty) qty=qty or 10; local ok,e=SaltRefiner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.seawaterCost then SaltRefiner.seawaterStock=SaltRefiner.seawaterStock-d.seawaterCost*qty end; if d.saltOreCost then SaltRefiner.saltOreStock=SaltRefiner.saltOreStock-d.saltOreCost*qty end; if d.waterCost then SaltRefiner.waterStock=SaltRefiner.waterStock-d.waterCost*qty end; if d.fuelCost then SaltRefiner.fuelStock=SaltRefiner.fuelStock-d.fuelCost*qty end; if d.silverCost then SaltRefiner.silverStock=SaltRefiner.silverStock-d.silverCost*qty end; if d.goldCost then SaltRefiner.goldStock=SaltRefiner.goldStock-d.goldCost*qty end; if d.jewelCost then SaltRefiner.jewelStock=SaltRefiner.jewelStock-d.jewelCost*qty end; local t=d.time; if SaltRefiner.maker then t=math.max(1,t-math.floor(SaltRefiner.maker.skill/12)) end; table.insert(SaltRefiner.activeMaking,{id="salt_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,purity=d.purity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SaltRefiner.completeMaking(m) local q=1.0+(SaltRefiner.getQualityBonus()/100); if SaltRefiner.maker then q=q+(SaltRefiner.maker.skill/180) end; q=math.min(2.0,q); SaltRefiner.productStock[m.productType]=(SaltRefiner.productStock[m.productType] or 0)+m.quantity; SaltRefiner.totalProducts=SaltRefiner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SaltRefiner.maker then SaltRefiner.maker.itemsMade=SaltRefiner.maker.itemsMade+m.quantity; if math.random()<0.20 then SaltRefiner.maker.skill=math.min(100,SaltRefiner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sol izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"salt.completed",{productName=m.productName,purity=m.purity}) end end
function SaltRefiner.update(dt) if not _G.state then return end; SaltRefiner.dayTimer=SaltRefiner.dayTimer+dt; if SaltRefiner.dayTimer>=30 then SaltRefiner.dayTimer=0; for i=#SaltRefiner.activeMaking,1,-1 do local m=SaltRefiner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SaltRefiner.completeMaking(m); table.remove(SaltRefiner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SaltRefiner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SaltRefiner.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SaltRefiner.getStats() return {seawaterStock=SaltRefiner.seawaterStock,saltOreStock=SaltRefiner.saltOreStock,waterStock=SaltRefiner.waterStock,fuelStock=SaltRefiner.fuelStock,silverStock=SaltRefiner.silverStock,goldStock=SaltRefiner.goldStock,jewelStock=SaltRefiner.jewelStock,productStock=SaltRefiner.productStock,numBuildings=#SaltRefiner.buildings,hasMaker=SaltRefiner.maker~=nil,makerName=SaltRefiner.maker and SaltRefiner.maker.name or "—",makerSkill=SaltRefiner.maker and SaltRefiner.maker.skill or 0,activeMaking=#SaltRefiner.activeMaking,totalProducts=SaltRefiner.totalProducts} end
return SaltRefiner
